def test_concurrent_idempotency_identity():
    responses = retry_same_identity_concurrently()
    order_ids = {response.json()["id"] for response in responses}
    assert len(order_ids) == 1
    assert len(STATE.orders) == 1

def test_webhook_event_is_applied_once():
    first = post_signed_webhook(event)
    second = post_signed_webhook(event)
    assert first.json() == {"status": "processed"}
    assert second.json() == {"status": "duplicate"}
